parameters.jsCode:
const contact = $('Search GHL — DV Inbound').item.json.contacts?.[0];
const customFields = contact?.customFields || [];

function getField(fieldId) {
  const field = customFields.find(f => f.id === fieldId);
  return field ? field.value : null;
}

const leadStatus = getField('YOUR_GHL_FIELD_ID_LEAD_STATUS'); // lead_status_sunpath

let callback_context = '';

if (leadStatus === 'no_answer_call_1') {
  callback_context = "We tried reaching them once before - they're calling back after seeing the missed call.";
} else if (leadStatus === 'no_answer_call_2') {
  callback_context = "We've tried reaching them a couple times now and sent a text - they're calling back after seeing the missed calls.";
} else if (leadStatus === 'exhausted') {
  callback_context = "We'd tried reaching them a few times before - they're calling back now after seeing the missed calls.";
}

return [{
  json: {
    dynamic_variables: {
      first_name: contact?.firstName || 'there',
      last_name: contact?.lastName || '',
      callback_context
    }
  }
}];

