const ORDINAL = (n) => {
  const s = ["th", "st", "nd", "rd"];
  const v = n % 100;
  return n + (s[(v - 20) % 10] || s[v] || s[0]);
};

const NUMBER_WORDS = {
  0: "zero", 1: "one", 2: "two", 3: "three", 4: "four", 5: "five",
  6: "six", 7: "seven", 8: "eight", 9: "nine", 10: "ten",
  11: "eleven", 12: "twelve", 13: "thirteen", 14: "fourteen", 15: "fifteen",
  16: "sixteen", 17: "seventeen", 18: "eighteen", 19: "nineteen",
  20: "twenty", 30: "thirty", 40: "forty", 50: "fifty"
};

function minuteWord(min) {
  // 1-9: "oh-" + digit word ("oh-five"). 10-59: natural spoken number, using the
  // same tens/ones compounding as NUMBER_WORDS already provides (e.g. "thirty-five").
  if (min < 10) return `oh-${NUMBER_WORDS[min]}`;
  if (NUMBER_WORDS[min]) return NUMBER_WORDS[min];
  const tens = Math.floor(min / 10) * 10;
  const ones = min % 10;
  return `${NUMBER_WORDS[tens]}-${NUMBER_WORDS[ones]}`;
}

function speakTime(isoString) {
  const d = new Date(isoString);
  if (isNaN(d.getTime())) return null;
  const opts = { timeZone: "America/New_York", hour: "numeric", minute: "numeric", hour12: true };
  const parts = new Intl.DateTimeFormat("en-US", opts).formatToParts(d);
  const hourNum = parseInt(parts.find(p => p.type === "hour").value, 10);
  const minute = parseInt(parts.find(p => p.type === "minute").value, 10);
  const dayPeriod = parts.find(p => p.type === "dayPeriod").value.toLowerCase();
  const hourWord = NUMBER_WORDS[hourNum] || String(hourNum);

  if (minute === 0) return `${hourWord} ${dayPeriod}`;
  return `${hourWord}-${minuteWord(minute)} ${dayPeriod}`;
}

function speakDateLabel(dateKey, todayKey, tomorrowKey) {
  const d = new Date(dateKey + "T12:00:00-04:00");
  if (isNaN(d.getTime())) return null;
  const weekday = new Intl.DateTimeFormat("en-US", { timeZone: "America/New_York", weekday: "long" }).format(d);
  const month = new Intl.DateTimeFormat("en-US", { timeZone: "America/New_York", month: "long" }).format(d);
  const dayNum = parseInt(new Intl.DateTimeFormat("en-US", { timeZone: "America/New_York", day: "numeric" }).format(d), 10);
  const dateLabel = `${weekday} ${month} ${ORDINAL(dayNum)}`;

  if (dateKey === todayKey) return `Today being ${dateLabel}`;
  if (dateKey === tomorrowKey) return `Tomorrow being ${dateLabel}`;
  return dateLabel;
}

function joinTimes(times) {
  if (times.length === 1) return `only availability is at ${times[0]}`;
  if (times.length === 2) return `at ${times[0]} and ${times[1]}`;
  return `at ${times.slice(0, -1).join(", ")}, and ${times[times.length - 1]}`;
}

function buildAvailabilityText(data) {
  const DATE_KEY_RE = /^\d{4}-\d{2}-\d{2}$/;

  const nowET = new Date(new Date().toLocaleString("en-US", { timeZone: "America/New_York" }));
  const todayKey = nowET.toISOString().slice(0, 10);
  const tomorrow = new Date(nowET);
  tomorrow.setDate(tomorrow.getDate() + 1);
  const tomorrowKey = tomorrow.toISOString().slice(0, 10);

  const sortedDateKeys = Object.keys(data).filter(k => DATE_KEY_RE.test(k)).sort();

  const lines = [];
  for (const dateKey of sortedDateKeys) {
    const rawSlots = data[dateKey]?.slots;
    if (!Array.isArray(rawSlots) || rawSlots.length === 0) continue;

    const dateLabel = speakDateLabel(dateKey, todayKey, tomorrowKey);
    if (dateLabel === null) continue; // invalid calendar date (e.g. month 13) - skip this day

    // Dedupe identical timestamps, then sort chronologically, then format.
    // A malformed individual slot (bad timestamp) is skipped rather than
    // aborting the whole day - one bad slot shouldn't hide the good ones.
    const uniqueSorted = [...new Set(rawSlots)].sort();
    const spokenTimes = uniqueSorted
      .map(speakTime)
      .filter(t => t !== null);
    if (spokenTimes.length === 0) continue;

    lines.push(`${dateLabel}: ${joinTimes(spokenTimes)}.`);
  }

  return lines.join("  \n");
}

let text = "";
try {
  const data = $input.first().json;
  if (data && typeof data === "object" && !Array.isArray(data)) {
    text = buildAvailabilityText(data);
  }
} catch (e) {
  // Any unexpected shape/parsing failure degrades to no availability rather
  // than crashing the node - the calling prompt already knows to tell the
  // lead a solar advisor will reach out directly when nothing is returned.
  text = "";
}

return [{ json: { text } }];

// This node's examples spell ordinals fully as words ("the seventh", "the
// thirtieth"), unlike the sibling Normal Availability Fine-tune node which
// never needed a written-out ordinal at all (it uses numeral+suffix: "18th").
// Table covers 1st-31st, the only range a calendar day-of-month can produce.
const ORDINAL_WORDS = {
  1: "first", 2: "second", 3: "third", 4: "fourth", 5: "fifth",
  6: "sixth", 7: "seventh", 8: "eighth", 9: "ninth", 10: "tenth",
  11: "eleventh", 12: "twelfth", 13: "thirteenth", 14: "fourteenth", 15: "fifteenth",
  16: "sixteenth", 17: "seventeenth", 18: "eighteenth", 19: "nineteenth", 20: "twentieth",
  21: "twenty-first", 22: "twenty-second", 23: "twenty-third", 24: "twenty-fourth", 25: "twenty-fifth",
  26: "twenty-sixth", 27: "twenty-seventh", 28: "twenty-eighth", 29: "twenty-ninth", 30: "thirtieth",
  31: "thirty-first",
};
const ORDINAL = (n) => ORDINAL_WORDS[n] || String(n);

const NUMBER_WORDS = {
  0: "zero", 1: "one", 2: "two", 3: "three", 4: "four", 5: "five",
  6: "six", 7: "seven", 8: "eight", 9: "nine", 10: "ten",
  11: "eleven", 12: "twelve", 13: "thirteen", 14: "fourteen", 15: "fifteen",
  16: "sixteen", 17: "seventeen", 18: "eighteen", 19: "nineteen",
  20: "twenty", 30: "thirty", 40: "forty", 50: "fifty"
};

function minuteWord(min) {
  if (min < 10) return `oh-${NUMBER_WORDS[min]}`;
  if (NUMBER_WORDS[min]) return NUMBER_WORDS[min];
  const tens = Math.floor(min / 10) * 10;
  const ones = min % 10;
  return `${NUMBER_WORDS[tens]}-${NUMBER_WORDS[ones]}`;
}

function speakTime(isoString) {
  const d = new Date(isoString);
  if (isNaN(d.getTime())) return null;
  const opts = { timeZone: "America/New_York", hour: "numeric", minute: "numeric", hour12: true };
  const parts = new Intl.DateTimeFormat("en-US", opts).formatToParts(d);
  const hourNum = parseInt(parts.find(p => p.type === "hour").value, 10);
  const minute = parseInt(parts.find(p => p.type === "minute").value, 10);
  const dayPeriod = parts.find(p => p.type === "dayPeriod").value.toLowerCase();
  const hourWord = NUMBER_WORDS[hourNum] || String(hourNum);

  if (minute === 0) return `${hourWord} ${dayPeriod}`;
  return `${hourWord}-${minuteWord(minute)} ${dayPeriod}`;
}

function speakOrdinalDateLabel(dateKey, todayKey, tomorrowKey) {
  // Note: this node's own examples use ordinal-only phrasing ("the seventh",
  // "the thirtieth") with NO weekday/month name in most outputs, unlike the
  // sibling Normal Availability Fine-tune node ("Wednesday June 18th"). Example
  // 1 output IS "Today being Wednesday the seventh" (weekday + ordinal, no
  // month) - so weekday is included, month is not. Followed exactly as given.
  const d = new Date(dateKey + "T12:00:00-04:00");
  if (isNaN(d.getTime())) return null;
  const weekday = new Intl.DateTimeFormat("en-US", { timeZone: "America/New_York", weekday: "long" }).format(d);
  const dayNum = parseInt(new Intl.DateTimeFormat("en-US", { timeZone: "America/New_York", day: "numeric" }).format(d), 10);
  const dateLabel = `${weekday} the ${ORDINAL(dayNum)}`;

  if (dateKey === todayKey) return { prefix: "today being", dateLabel };
  if (dateKey === tomorrowKey) return { prefix: "tomorrow being", dateLabel };
  return { prefix: null, dateLabel };
}

function buildSoonestText(data) {
  const DATE_KEY_RE = /^\d{4}-\d{2}-\d{2}$/;

  const nowET = new Date(new Date().toLocaleString("en-US", { timeZone: "America/New_York" }));
  const todayKey = nowET.toISOString().slice(0, 10);
  const tomorrow = new Date(nowET);
  tomorrow.setDate(tomorrow.getDate() + 1);
  const tomorrowKey = tomorrow.toISOString().slice(0, 10);

  const sortedDateKeys = Object.keys(data).filter(k => DATE_KEY_RE.test(k)).sort();

  // Flatten to a single chronological list of { dateKey, iso } across all days,
  // then take the first two overall (not first two per day) - matches "select
  // only the first two available slots across all provided days."
  const allSlots = [];
  for (const dateKey of sortedDateKeys) {
    const rawSlots = data[dateKey]?.slots;
    if (!Array.isArray(rawSlots)) continue;
    const uniqueSorted = [...new Set(rawSlots)].sort();
    for (const iso of uniqueSorted) {
      allSlots.push({ dateKey, iso });
    }
  }

  const picked = allSlots.slice(0, 2);
  if (picked.length === 0) return "";

  // Group picked slots by date (both picks might land on the same day, or two
  // different days) - build one clause per distinct date among the picks.
  const byDate = [];
  for (const slot of picked) {
    let group = byDate.find((g) => g.dateKey === slot.dateKey);
    if (!group) {
      group = { dateKey: slot.dateKey, times: [] };
      byDate.push(group);
    }
    group.times.push(slot.iso);
  }

  const clauses = [];
  for (const group of byDate) {
    const label = speakOrdinalDateLabel(group.dateKey, todayKey, tomorrowKey);
    if (label === null) continue;
    const spokenTimes = group.times.map(speakTime).filter((t) => t !== null);
    if (spokenTimes.length === 0) continue;

    const prefixPart = label.prefix ? `${label.prefix} ${label.dateLabel}` : label.dateLabel;
    if (spokenTimes.length === 1) {
      clauses.push(`${prefixPart} at ${spokenTimes[0]}`);
    } else {
      // two times on the same day: "<label> at <time1> Eastern and also at <time2>"
      clauses.push(`${prefixPart} at ${spokenTimes[0]} Eastern and also at ${spokenTimes[1]}`);
    }
  }

  if (clauses.length === 0) return "";

  // The real live node's output includes the full carrier sentence, not just
  // the clause - confirmed against a real live execution (id 16711,
  // Micah Talbot call, 2026-08-24): the node's own "text" field literally
  // contains "We have availability <clause>. When works for you?" - this is
  // spoken verbatim by the assistant per its tool-usage instructions, so the
  // wrapper must be included here, not left to the caller of this node.
  let inner;
  if (clauses.length === 1) {
    inner = clauses[0];
  } else {
    // two different days: join with "and", second clause needs its own
    // "Eastern" dropped per the examples (only the first clause says it)
    inner = `${clauses[0]} Eastern and ${clauses[1]}`;
  }
  return `We have availability ${inner}. When works for you?`;
}

let text = "";
try {
  // Reads raw GHL slot data directly from Get Available Slots GHL by node
  // reference rather than $input.first().json - this node may sit downstream
  // of Format Availability (Code) on canvas (its formatted {text: "..."} output
  // would otherwise arrive here instead of raw {date: {slots: [...]}} data),
  // matching how the original LLM prompt for this node explicitly referenced
  // Get Available Slots GHL by name rather than trusting whatever fed it.
  const data = $("Get Available Slots GHL").first().json;
  if (data && typeof data === "object" && !Array.isArray(data)) {
    text = buildSoonestText(data);
  }
} catch (e) {
  text = "";
}

return [{ json: { text } }];

const reason = ($json.disqualification_reason || "").toLowerCase();
const summary = ($json.call_summary || "").toLowerCase();
const combined = `${reason} ${summary}`;

// Telnyx's AI insight writes disqualification_reason/call_summary freely from
// the real transcript - when Alex initially told a lead they qualified based on
// a misheard number, then had to walk that back after a correction, the model
// tends to describe it using language like this. Not a fixed field Telnyx sets -
// inferred from free text, so this is a heuristic, not a guarantee.
const mishearingSignals = [
  "mishear",
  "misheard",
  "mis-hear",
  "corrected",
  "correction",
  "initially qualified",
  "initially told",
  "originally qualified",
  "originally told",
  "walked back",
  "mix-up",
  "mix up",
  "misunderstood",
];

const followedMishearing = mishearingSignals.some((s) => combined.includes(s));

return [
  {
    json: {
      ...$json,
      needs_human_followup: followedMishearing ? "true" : "false",
    },
  },
];

const callSid = $('Telnyx Call Status Webhook').item.json.body.CallSid;
const handled = $json.handledValue === 'true';
return [{ json: { callSid, handled } }];

const conversationId = $('If Conversation Found').item.json.data[0].id;
const callSid = $('Telnyx Call Status Webhook').item.json.body.CallSid;
const metadata = $('If Conversation Found').item.json.data[0].metadata || {};

const insightsEntry = $json.data[0] || {};
const conversationInsights = insightsEntry.conversation_insights || [];
const status = insightsEntry.status;

const CALL_ANALYSIS_INSIGHT_ID = 'YOUR_TELNYX_INSIGHT_ID';
const analysisInsight = conversationInsights.find(i => i.insight_id === CALL_ANALYSIS_INSIGHT_ID);

let parsed;
if (status !== 'completed' || !analysisInsight) {
  parsed = {
    call_outcome: 'no_meaningful_conversation',
    call_summary: `Could not retrieve call insights (status: ${status || 'unknown'}).`,
    user_sentiment: 'unknown',
    call_successful: 'no',
    callback_time_requested: 'none',
    disqualification_reason: 'n/a',
    transcript_text: '',
    parse_error: true
  };
} else {
  try {
    parsed = JSON.parse(analysisInsight.result);
  } catch (e) {
    parsed = {
      call_outcome: 'no_meaningful_conversation',
      call_summary: analysisInsight.result || 'Could not parse insight result',
      user_sentiment: 'unknown',
      call_successful: 'no',
      callback_time_requested: 'none',
      disqualification_reason: 'n/a',
      transcript_text: '',
      parse_error: true
    };
  }
}

return [{
  json: {
    ...parsed,
    recording_url: null,
    call_duration_secs: null,
    metadata_to: metadata.to || null,
    conversation_id: conversationId,
    recovered_via_timeout: true
  }
}];

