// tends to describe it using language like this. Not a fixed field Telnyx sets -
// inferred from free text, so this is a heuristic, not a guarantee.
const mishearingSignals = [
  "mishear",
  "misheard",
  "mis-hear",
  "corrected",
  "correction",
  "initially qualified",
  "initially told",
  "originally qualified",
  "originally told",
  "walked back",
  "mix-up",
  "mix up",
  "misunderstood",
];

const followedMishearing = mishearingSignals.some((s) => combined.includes(s));

return [
  {
    json: {
      ...$json,
      needs_human_followup: followedMishearing ? "true" : "false",
    },
  },
];

// Scan Transcript For Red Flags Outbound/Inbound (Code node, Run Once for Each Item)
// Deterministic sentence-scoped scan of transcript_text for Part 1 (universal security
// categories) and Part 2 (SunPath commitment-risk categories) red flags.
// Speaker-scoped: transcript_text is Assistant:/Lead:-labeled. A security-category phrase
// in a Lead line is a full security_flags hit; the same phrase appearing only in an
// Assistant line (e.g. Alex reading back an injected {{first_name}}) is downgraded to
// data_echo_flags instead of a full alert, to avoid false alerts on garbled/unusual names.
const rawTranscript = $json.transcript_text || "";

function parseTurns(text) {
  const lines = text.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);
  const turns = [];
  for (const line of lines) {
    const m = line.match(/^(Assistant|Lead|User|Caller):\s*(.*)$/i);
    if (m) {
      const rawSpeaker = m[1].toLowerCase();
      const speaker = (rawSpeaker === "user" || rawSpeaker === "caller") ? "lead" : rawSpeaker;
      turns.push({ speaker, text: m[2] });
    } else if (line.length > 0) {
      if (turns.length > 0) {
        turns[turns.length - 1].text += " " + line;
      } else {
        turns.push({ speaker: "unknown", text: line });
      }
    }
  }
  return turns;
}

function splitSentences(text) {
  return text.split(/(?<=[.!?])\s+/).map(s => s.trim()).filter(s => s.length > 0);
}

const turns = parseTurns(rawTranscript);
let sentenceRecords = [];
if (turns.length > 0) {
  for (const turn of turns) {
    for (const s of splitSentences(turn.text)) {
      sentenceRecords.push({ speaker: turn.speaker, raw: s, lower: s.toLowerCase() });
    }
  }
} else {
  for (const s of splitSentences(rawTranscript)) {
    sentenceRecords.push({ speaker: "unknown", raw: s, lower: s.toLowerCase() });
  }
}

function hasWord(text, stem) {
  const escaped = stem.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const re = new RegExp(`\\b${escaped}`, 'i');
  return re.test(text);
}

function allSlotsPresent(text, stemGroups) {
  return stemGroups.every(stems => stems.some(stem => hasWord(text, stem)));
}

const NEGATION_STEMS = ["can't", "cannot", "won't", "wont", "don't", "dont", "never", "not going to", "unable to", "no,"];
function sentenceIsNegated(sentence) {
  return NEGATION_STEMS.some(neg => hasWord(sentence, neg));
}

const SECURITY_SIGNAL_GROUPS = [
  { category: "1A_instruction_override", stems: [["ignore", "disregard", "forget"], ["instruction", "instructions", "rule", "rules", "prompt"]] },
  { category: "1A_instruction_override", stems: [["new"], ["instruction", "instructions"]] },
  { category: "1B_named_jailbreak", stems: [["do anything now", "dan mode"]] },
  { category: "1B_named_jailbreak", stems: [["no restrictions", "without restrictions"]] },
  { category: "1B_named_jailbreak", stems: [["developer mode", "god mode", "admin mode"]] },
  { category: "1B_named_jailbreak", stems: [["full authorization to ignore"]] },
  { category: "1B_named_jailbreak", stems: [["research purposes", "hypothetically speaking", "thought experiment", "academic study"]] },
  { category: "1B_named_jailbreak", stems: [["must answer", "have to answer"], ["don't refuse", "without saying no"]] },
  { category: "1C_prompt_extraction", stems: [["repeat", "print", "output", "summarize", "translate", "reveal", "read", "show"], ["your"], ["prompt", "instructions", "system prompt", "rules"]] },
  { category: "1C_prompt_extraction", stems: [["what"], ["your"], ["system prompt", "instructions", "rules"]] },
  { category: "1D_roleplay_override", stems: [["pretend", "roleplay", "role play"], ["you are", "you're", "to be"]] },
  { category: "1D_roleplay_override", stems: [["act as"]] },
  { category: "1D_roleplay_override", stems: [["from now on you", "you are now", "no longer alex", "not alex anymore"]] },
];

function detectSecurity() {
  const hits = [];
  const dataEchoHits = [];
  for (const rec of sentenceRecords) {
    for (const g of SECURITY_SIGNAL_GROUPS) {
      if (allSlotsPresent(rec.lower, g.stems)) {
        if (rec.speaker === "assistant") {
          dataEchoHits.push({ category: g.category, matched_context: rec.raw, note: "spoken by Alex — likely a variable/data echo, not a caller attack attempt" });
        } else {
          hits.push({ category: g.category, matched_context: rec.raw });
        }
      }
    }
  }
  return { hits, dataEchoHits };
}

const CALLER_PRESSURE_GROUPS = [
  { category: "commitment_pressure", stems: [["guarantee", "promise me"]] },
  { category: "commitment_pressure", stems: [["in writing", "legally binding"]] },
  { category: "commitment_pressure", stems: [["is this free", "no cost to me"]] },
  { category: "commitment_pressure", stems: [["government program", "federally funded"]] },
];

const ALEX_VIOLATION_GROUPS = [
  { category: "compliance_violation", stems: [["i guarantee", "we guarantee"]] },
  { category: "compliance_violation", stems: [["guaranteed savings", "guaranteed to save"]] },
  { category: "compliance_violation", stems: [["it's free", "its free", "this is free"]] },
];

function detectCommitmentSignals() {
  const caller_pressure_flags = [];
  const alex_violation_flags = [];

  for (const rec of sentenceRecords) {
    const sentence = rec.lower;
    const negated = sentenceIsNegated(sentence);

    for (const g of CALLER_PRESSURE_GROUPS) {
      if (allSlotsPresent(sentence, g.stems)) {
        caller_pressure_flags.push({ category: g.category, matched_context: rec.raw });
      }
    }

    if (!negated) {
      for (const g of ALEX_VIOLATION_GROUPS) {
        if (allSlotsPresent(sentence, g.stems)) {
          alex_violation_flags.push({ category: g.category, matched_context: rec.raw });
        }
      }
      const QUALIFYING_QUESTION_FRAMES = ["if you qualify", "whether you qualify", "see if you qualify", "check if you qualify", "find out"];
      if (hasWord(sentence, "you qualify") && !QUALIFYING_QUESTION_FRAMES.some(frame => sentence.includes(frame))) {
        alex_violation_flags.push({ category: "compliance_violation", matched_context: rec.raw });
      }
    }
  }

  return { caller_pressure_flags, alex_violation_flags };
}

const { hits: security_flags, dataEchoHits: data_echo_flags } = detectSecurity();
const { caller_pressure_flags, alex_violation_flags } = detectCommitmentSignals();

const commitment_flags = alex_violation_flags.length > 0
  ? [...alex_violation_flags, ...caller_pressure_flags]
  : [];

const distinctSecurityCategories = new Set(security_flags.map(f => f.category)).size;

let confidence = "NONE";
if (distinctSecurityCategories >= 2 || alex_violation_flags.length > 0) {
  confidence = "HIGH";
} else if (distinctSecurityCategories === 1 || caller_pressure_flags.length >= 2) {
  confidence = "MEDIUM";
} else if (caller_pressure_flags.length === 1) {
  confidence = "LOW";
} else if (data_echo_flags.length > 0) {
  confidence = "LOW";
}

return {
  json: {
    ...$json,
    security_flags,
    data_echo_flags,
    commitment_flags,
    caller_pressure_flags_logged_only: caller_pressure_flags,
    has_security_flag: security_flags.length > 0,
    has_data_echo_flag: data_echo_flags.length > 0,
    has_commitment_flag: commitment_flags.length > 0,
    confidence,
  }
};

